export type FbtTier = {
  label: string;
  maxOz: number;
  /** Fee per unit in USD for orders of 1, 2, 3 and 4+ units. */
  perUnit: readonly [number, number, number, number];
};

type Row = readonly [label: string, maxOz: number, one: number, two: number, three: number, fourPlus: number];

