export const fbtRateCard = {
  market: "US",
  currency: "USD",
  effectiveDate: "2026-11-01",
  source: {
    title: "FBT Rate Card & Frequently Asked Questions (TikTok Shop Seller University)",
    url: "https://seller-us.tiktok.com/university/essay?knowledge_id=3507056320268087&lang=en",
  },
  orderSizes: ["1 unit order", "2 units order", "3 units order", "4+ units order"],
  /** Actual weight only when the item is at most this weight and volume; otherwise the greater of actual and dimensional weight. */
  actualWeightOnly: { maxLb: 2, maxCubicInches: 332 },
  dimensionalDivisor: 166,
  maxItemLb: 150,
  maxSideInches: 108,
  tiers: rows.map(([label, maxOz, ...perUnit]): FbtTier => ({ label, maxOz, perUnit })),
} as const;

export function fbtBillableWeightLb(actualLb: number, lengthIn: number, widthIn: number, heightIn: number) {
  if (![actualLb, lengthIn, widthIn, heightIn].every(value => Number.isFinite(value) && value > 0)) {
    throw new RangeError("Weight and dimensions must be finite positive numbers.");
  }
  const volume = lengthIn * widthIn * heightIn;
  const { maxLb, maxCubicInches } = fbtRateCard.actualWeightOnly;
  if (actualLb <= maxLb && volume <= maxCubicInches) return actualLb;
  return Math.max(actualLb, volume / fbtRateCard.dimensionalDivisor);
}

export function findFbtTier(billableWeightLb: number) {
  if (!Number.isFinite(billableWeightLb) || billableWeightLb <= 0) {
    throw new RangeError("Billable weight must be a finite positive number.");
  }
  const oz = Number((billableWeightLb * 16).toPrecision(12));
  return fbtRateCard.tiers.find(tier => oz <= tier.maxOz);
}

/** Per-unit FBT fulfillment fee, or undefined when the weight is above the FBT item limit. */
export function fbtFeePerUnit(billableWeightLb: number, unitsInOrder = 1) {
  if (!Number.isInteger(unitsInOrder) || unitsInOrder < 1) {
    throw new RangeError("Units in order must be a positive whole number.");
  }
  return findFbtTier(billableWeightLb)?.perUnit[Math.min(unitsInOrder, 4) - 1];
}
